import java.util.*;

class Solution {
  public String minimizeError(String[] prices, int target) {
    // work in thousandths to avoid floating-point error
    long floorSum = 0, error = 0;
    List<Integer> fracs = new ArrayList<>();
    for (String p : prices) {
      long milli = Math.round(Double.parseDouble(p) * 1000);
      floorSum += milli / 1000;
      int frac = (int) (milli % 1000);
      if (frac > 0) fracs.add(frac);
      error += frac; // everything floored to start
    }
    long ups = target - floorSum; // how many prices must be rounded up instead
    if (ups < 0 || ups > fracs.size()) return "-1";
    fracs.sort(Collections.reverseOrder()); // rounding up the largest fractions costs least
    for (int i = 0; i < ups; i++) error += 1000 - 2L * fracs.get(i);
    return String.format("%d.%03d", error / 1000, error % 1000);
  }
}
